<# .SYNOPSIS Generate a one‑click AWS Console login URL for IAM user Antigravvity. .DESCRIPTION This script obtains a temporary federation token using AWS CLI, exchanges it for a sign‑in token via the AWS federation endpoint, and builds a URL that logs the user directly into the AWS Console. No manual password entry is required. .REQUIREMENTS - AWS CLI v2 installed and configured with permissions to call sts:GetFederationToken (AdministratorAccess attached to the user). - PowerShell 5.1+ (Windows) or PowerShell 7. .CONFIGURATION $IamUserName = 'Antigravvity' # IAM user $SessionName = $IamUserName + '-session' $DurationSec = 43200 # 12 hours (max) $Policy = $null # Set a JSON policy string to limit permissions, or leave null for full user permissions. .STEP1 # Request a federation token $fedArgs = @('sts','get-federation-token','--name',$SessionName,'--duration-seconds',$DurationSec) if($Policy){ $fedArgs += '--policy',$Policy } $fedJson = aws @fedArgs --output json if(-not $fedJson){ Write-Error 'Unable to obtain federation token.'; exit 1 } $fed = $fedJson | ConvertFrom-Json $AccessKeyId = $fed.Credentials.AccessKeyId $SecretAccessKey = $fed.Credentials.SecretAccessKey $SessionToken = $fed.Credentials.SessionToken .STEP2 # Build session payload $sessionPayload = @{sessionId=$AccessKeyId;sessionKey=$SecretAccessKey;sessionToken=$SessionToken} | ConvertTo-Json -Compress $federationBase = 'https://signin.aws.amazon.com/federation' $signinUrl = $federationBase + '?Action=getSigninToken&SessionDuration=' + $DurationSec + '&Session=' + [uri]::EscapeDataString($sessionPayload) $signinResponse = Invoke-RestMethod -Uri $signinUrl if(-not $signinResponse.SigninToken){ Write-Error 'Failed to get sign‑in token.'; exit 1 } $SigninToken = $signinResponse.SigninToken .STEP3 # Build final console URL $Destination = '/console/home' $ConsoleUrl = $federationBase + '?Action=login&Issuer=' + $IamUserName + '&Destination=' + [uri]::EscapeDataString($Destination) + '&SigninToken=' + $SigninToken Write-Host '`n=== AWS Console login URL ===' $ConsoleUrl $outFile = Join-Path -Path (Split-Path -Parent $MyInvocation.MyCommand.Path) -ChildPath 'aws_console_login_url.txt' Set-Content -Path $outFile -Value $ConsoleUrl -Encoding UTF8 Write-Host '`nURL saved to:' $outFile